             })

    MockSlack.respond("conversations.list", %{
      "ok" => true,
      "channels" => [
        %{"id" => "C_PUBLIC", "name" => "general", "is_member" => true},
        %{
          "id" => "C_PRIVATE",
          "name" => "planning",
          "is_private" => true,
          "is_member" => true
        },
        %{"id" => "C_SHARED", "name" => "partner", "is_shared" => true},
        %{"id" => "C_ARCHIVED", "name" => "old", "is_archived" => true},
        %{"id" => "", "name" => "malformed"}
      ],
      "response_metadata" => %{"next_cursor" => "channel-page-2"}
    })

    assert {:ok,
            %{
              channels: [
                %{
                  id: "C_PUBLIC",
                  name: "general",
                  private?: false,
                  shared?: false,
                  member?: true
                },
                %{
                  id: "C_PRIVATE",
                  name: "planning",
                  private?: true,
                  shared?: false,
                  member?: true
                },
                %{
                  id: "C_SHARED",
                  name: "partner",
                  private?: false,
                  shared?: true,
                  member?: false
                }
              ],
              next_cursor: "channel-page-2"
            } = page} =
             SalixIM.ProviderConnects.list_slack_triage_channels(
