             SalixIM.ProviderConnects.get_slack_triage_authority(
               tenant,
               group_id,
               connect["connect_id"]
             )

    assert :ok =
             SalixIM.ProviderConnects.set_slack_triage_enabled(
               tenant,
               group_id,
               connect["connect_id"],
               true
             )

    assert :ok =
             SalixIM.ProviderConnects.delete_im_connect(
               tenant,
               group_id,
               connect["connect_id"]
             )

    assert {:error, :slack_triage_authority_ineligible} =
             SalixIM.ProviderConnects.get_slack_triage_authority(
               tenant,
               group_id,
               connect["connect_id"]
             )

    assert {:error, :slack_triage_authority_ineligible} =
             SalixIM.ProviderConnects.set_slack_triage_enabled(
               tenant,
               group_id,
               connect["connect_id"],
               false
             )
  end

