      delivery = %{
        "delivery_id" => "#{group_id}:#{conversation_id}:#{message_id}:#{participant_id}",
        "status" => "pending",
        "agent_group_id" => group_id,
        "conversation_id" => conversation_id,
        "message_id" => message_id,
