               call(agent_id, "slack", "slack.post_message", connect_id, %{
                 "channel" => "C9",
                 "text" => "bounded retry"
               })

      assert length(MockSlack.requests("chat.postMessage")) == 2
    end

    test "Slack tool retry configuration cannot exceed the hard count or deadline caps", %{
      agent_id: agent_id,
