              "actor_type" => "user",
              "user_id" => "current",
              "state" => "active",
              "notification_filter" => %{"messages" => "all", "statuses" => "none"}
            },
            agent_participant(conversation_id, worker_id, "worker", "ses1_1100000000000000001", %{
              "actor_type" => "agent",
              "role_label" => "worker"
            }),
            agent_participant(
              conversation_id,
              router_id,
              "delegator",
              "ses1_1100000000000000002",
              %{
                "actor_type" => "agent",
                "role_label" => "delegator"
              }
            )
          ]
        })

