      slack_envelope("Ev-thread-mention-cache-follow-up", %{
        "type" => "message",
        "user" => "U2",
        "text" => "continue without another mention",
        "channel" => "C-thread-mention-cache",
        "channel_type" => "channel",
        "ts" => "105.000014",
        "event_ts" => "999.000014",
        "thread_ts" => "105.000000"
      })

