    textual_mention =
      put_in(real_mention, ["header", "event_id"], "evt_meeting_textual")
      |> put_in(["event", "message", "message_id"], "om_meeting_textual")
      |> put_in(["event", "message", "mentions"], [])
      |> put_in(
        ["event", "message", "content"],
