        "bot_user_id" => "Ubot",
        "oauth_completed_at" => 1,
        "inbound_agent_id" => router["agent_id"]
      })

    slack_envelope = %{
      "type" => "event_callback",
      "api_app_id" => "A-retry",
      "team_id" => "T-retry",
      "event_id" => "Ev-retry",
      "event" => %{
        "type" => "app_mention",
        "user" => "U1",
        "text" => "<@Ubot> retry slack",
        "channel" => "C1",
        "ts" => "123.456"
      }
